#!/usr/bin/env node
// kar-canon — Agensi skill script, generated by build.mjs in the sjgant80-hub/kar-canon repository.
// The KERNEL block below is byte-identical to the logic of the live page (index.html) and to
// kernel.mjs, which the tests and the witness mutation gate run against. No network, no dependencies,
// writes no files: it reads the input you name and prints a JSON report to stdout.
// Powered by the Konomi architecture, created by Thomas Frumkin. MIT licence.
// ---- KERNEL (from index.html) ----
var ALGO_VERSION = "kar-canon-v1";

// ---------- canonicalization core ----------

function canonNumber(n) {
  if (Object.is(n, -0)) return "0";
  if (!isFinite(n)) throw new Error("non-finite number encountered");
  return String(n);
}

function canonString(s) {
  return JSON.stringify(s);
}

function canonicalize(value) {
  if (value === null) return "null";
  const t = typeof value;
  if (t === "boolean") return value ? "true" : "false";
  if (t === "number") return canonNumber(value);
  if (t === "string") return canonString(value);
  if (Array.isArray(value)) {
    return "[" + value.map(canonicalize).join(",") + "]";
  }
  if (t === "object") {
    const keys = Object.keys(value).sort();
    return "{" + keys.map(function (k) { return canonString(k) + ":" + canonicalize(value[k]); }).join(",") + "}";
  }
  throw new Error("unsupported JSON value type: " + t);
}

async function sha256Hex(str) {
  const buf = new TextEncoder().encode(str);
  const digest = await crypto.subtle.digest("SHA-256", buf);
  return Array.from(new Uint8Array(digest)).map(function (b) { return b.toString(16).padStart(2, "0"); }).join("");
}

function typeOf(v) {
  if (v === null) return "null";
  if (Array.isArray(v)) return "array";
  return typeof v;
}

function diffTrees(a, b, path) {
  path = path || "$";
  const diffs = [];
  const ta = typeOf(a), tb = typeOf(b);
  if (ta !== tb) {
    diffs.push({ path: path, kind: "type-changed", from: a, to: b });
    return diffs;
  }
  if (ta === "object") {
    const keys = new Set(Object.keys(a).concat(Object.keys(b)));
    Array.from(keys).sort().forEach(function (k) {
      const p = path + "." + k;
      if (!(k in a)) diffs.push({ path: p, kind: "added", to: b[k] });
      else if (!(k in b)) diffs.push({ path: p, kind: "removed", from: a[k] });
      else diffs.push.apply(diffs, diffTrees(a[k], b[k], p));
    });
  } else if (ta === "array") {
    const len = Math.max(a.length, b.length);
    for (let i = 0; i < len; i++) {
      const p = path + "[" + i + "]";
      if (i >= a.length) diffs.push({ path: p, kind: "added", to: b[i] });
      else if (i >= b.length) diffs.push({ path: p, kind: "removed", from: a[i] });
      else diffs.push.apply(diffs, diffTrees(a[i], b[i], p));
    }
  } else {
    if (a !== b) diffs.push({ path: path, kind: "changed", from: a, to: b });
  }
  return diffs;
}

async function compareDocs(jsonA, jsonB) {
  const a = JSON.parse(jsonA);
  const b = JSON.parse(jsonB);
  const ca = canonicalize(a);
  const cb = canonicalize(b);
  const ha = await sha256Hex(ca);
  const hb = await sha256Hex(cb);
  const match = ha === hb;
  return { a: a, b: b, ca: ca, cb: cb, ha: ha, hb: hb, match: match, diffs: match ? [] : diffTrees(a, b) };
}

// ---------- self-test (the page runs these on load; the skill script runs them with --selftest) ----------

const SELFTESTS = [
  { name: "Key order + whitespace differ, same data", a: '{"b": 2, "a": 1}', b: '{\n  "a":   1,\n  "b":2\n}', expect: "match" },
  { name: "Number formatting: 1.50 vs 1.5", a: '{"x": 1.50}', b: '{"x": 1.5}', expect: "match" },
  { name: "Number formatting: 1e2 vs 100", a: '{"x": 1e2}', b: '{"x": 100}', expect: "match" },
  { name: "Unicode escape vs literal character", a: '{"name": "caf\\u00e9"}', b: '{"name": "café"}', expect: "match" },
  { name: "Negative zero canonicalizes to 0", a: '{"x": -0}', b: '{"x": 0}', expect: "match" },
  { name: "Duplicate keys resolve last-value-wins", a: '{"x":1,"x":2}', b: '{"x":2}', expect: "match" },
  { name: "Tampered numeric value is caught and pinpointed", a: '{"amount": 100, "currency": "USD"}', b: '{"amount": 150, "currency": "USD"}', expect: "differ", expectPath: "$.amount" },
  { name: "Array reorder is DIFFER (arrays are order-sensitive)", a: '{"tags": ["a","b","c"]}', b: '{"tags": ["c","b","a"]}', expect: "differ" },
  { name: "Added key is caught and pinpointed", a: '{"a":1}', b: '{"a":1,"b":2}', expect: "differ", expectPath: "$.b" },
  { name: 'Type mismatch: "1" (string) vs 1 (number) is DIFFER', a: '{"x":"1"}', b: '{"x":1}', expect: "differ" }
];

async function runSelfTests(list) {
  list = list || SELFTESTS;
  const results = [];
  for (const t of list) {
    let ok = false, detail = "";
    try {
      const r = await compareDocs(t.a, t.b);
      const got = r.match ? "match" : "differ";
      ok = got === t.expect;
      if (ok && t.expectPath) {
        ok = r.diffs.some(function (d) { return d.path === t.expectPath; });
      }
      if (!ok) detail = " (expected " + t.expect + (t.expectPath ? " at " + t.expectPath : "") + ", got " + got + ")";
    } catch (e) {
      ok = false; detail = " (error: " + e.message + ")";
    }
    results.push({ name: t.name, ok: ok, detail: detail });
  }
  return results;
}
// ---- CLI (from cli.mjs) ----
// cli.mjs — Kar-Canon on the command line. build.mjs bundles this with the KERNEL block of index.html into
// scripts/kar-canon.mjs, the single file the Agensi skill runs. It canonicalises two JSON documents, hashes
// each canonical form with SHA-256 and says whether they are the same data, and if not, exactly where not.
// Exit 0 = MATCH · 1 = DIFFER (or a self-check failed) · 2 = the input could not be used.
import { readFileSync } from 'node:fs';

const USAGE = `usage: node kar-canon.mjs <a.json> <b.json>     compare two JSON files (either may be - for stdin)
       node kar-canon.mjs <input.json | ->         input: {"a": <any JSON value>, "b": <any JSON value>}
       node kar-canon.mjs --selftest               run the page's built-in self-checks
output: a JSON report on stdout. exit 0 = MATCH, 1 = DIFFER, 2 = bad input`;

class InputError extends Error {}
const fail = (msg) => { throw new InputError(msg); };

function readText(path) {
  try { return readFileSync(path === '-' ? 0 : path, 'utf8'); }
  catch (e) { return fail(`cannot read ${path === '-' ? 'stdin' : path}: ${e.code || e.message}`); }
}
function checkJson(text, what) {
  try { JSON.parse(text); } catch (e) { fail(`${what} is not valid JSON (${e.message})`); }
  return text;
}

async function canon(textA, textB) {
  const r = await compareDocs(textA, textB);
  return {
    exitCode: r.match ? 0 : 1,
    report: {
      tool: 'kar-canon',
      algorithm: ALGO_VERSION,
      verdict: r.match ? 'MATCH' : 'DIFFER',
      a: { sha256: r.ha, canonical: r.ca },
      b: { sha256: r.hb, canonical: r.cb },
      diffs: r.diffs,
    },
  };
}

async function main(args) {
  if (args.length === 1 && args[0] === '--selftest') {
    const results = await runSelfTests();
    const passed = results.filter((t) => t.ok).length;
    process.stdout.write(JSON.stringify({ tool: 'kar-canon', algorithm: ALGO_VERSION, selftest: results, passed, total: results.length }, null, 2) + '\n');
    return passed === results.length ? 0 : 1;
  }
  let textA, textB;
  if (args.length === 2) {
    if (args[0] === '-' && args[1] === '-') fail('only one of the two documents can come from stdin');
    textA = checkJson(readText(args[0]), args[0] === '-' ? 'stdin' : args[0]);
    textB = checkJson(readText(args[1]), args[1] === '-' ? 'stdin' : args[1]);
  } else if (args.length === 1 && args[0] !== '-h' && args[0] !== '--help') {
    let input;
    try { input = JSON.parse(readText(args[0])); } catch (e) { if (e instanceof InputError) throw e; fail(`the input is not valid JSON (${e.message})`); }
    if (!input || typeof input !== 'object' || Array.isArray(input) || !('a' in input) || !('b' in input)) {
      fail('a single input must be an object with "a" and "b" (the two JSON values to compare)');
    }
    textA = JSON.stringify(input.a);
    textB = JSON.stringify(input.b);
  } else {
    process.stderr.write(USAGE + '\n');
    return 2;
  }
  const { exitCode, report } = await canon(textA, textB);
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
  return exitCode;
}

try {
  process.exitCode = await main(process.argv.slice(2));
} catch (e) {
  process.stderr.write(`kar-canon: ${e instanceof InputError ? e.message : 'internal error: ' + (e && e.message)}\n`);
  process.exitCode = e instanceof InputError ? 2 : 3;
}
